#include <bits/stdc++.h>

using namespace std;

#define INF (1 << 30)
#define MAXN 110

char s[MAXN];
int b[MAXN];

int main() {
    int n;
    while (scanf("%d", &n) > 0) {
        scanf("%s", s);

        int ans = 0;
        for (int i = 0; i < n; i++) {
            scanf("%d", &b[i]);
            ans += b[i];
        }

        for (int i = 0; i + i < n; i++) {
            if (b[i] > b[n - 1 - i]) {
                swap(b[i], b[n - 1 - i]);
            }
        }

        for (int i = 0; i + i < n; i++) {
            if (s[i] != s[n - 1 - i]) continue;

            for (int j = i + 1; j + j < n; j++) {
                if (s[j] != s[i] && s[j] == s[n - 1 - j]) {
                    swap(s[i], s[j]);
                    ans -= b[i] + b[j];
                    b[i] = b[j] = 0;
                    break;
                }
            }
        }

        for (int i = 0; i + i < n; i++) {
            if (s[i] != s[n - 1 - i]) continue;

            int k = -1, min_b = INF;
            for (int j = 0; j + j < n; j++) {
                if (s[j] != s[i] && b[j] < min_b) {
                    k = j;
                    min_b = b[j];
                }
            }

            swap(s[i], s[k]);
            ans -= b[i] + b[k];
            b[i] = b[k] = 0;
        }

        printf("%d\n", ans);
    }

    return 0;
}

